/** Agent portraits: one head image per mood, generated by the control plane. */

export const AVATAR_MOODS = ['neutral', 'happy', 'fearful', 'doubt'] as const;
export type AvatarMood = (typeof AVATAR_MOODS)[number];

export const AVATAR_MOOD_LABEL: Record<AvatarMood, string> = {
  neutral: 'Neutral',
  happy: 'Happy',
  fearful: 'Fearful',
  doubt: 'In doubt',
};

export interface AvatarMeta {
  prompt: string;
  model: string;
  by: string;
  generatedAt: string;
  moods: Partial<Record<AvatarMood, { generatedAt: string }>>;
}

export interface AvatarJob {
  state: 'running' | 'done' | 'failed';
  startedAt: string;
  moods: Partial<Record<AvatarMood, 'pending' | 'running' | 'done' | 'failed'>>;
  error?: string;
}

export interface AvatarStatus {
  enabled: boolean;
  model: string;
  meta?: AvatarMeta;
  job?: AvatarJob;
}

/** Mood of a task as shown next to it. */
export function moodForTaskStatus(status: string): AvatarMood {
  switch (status) {
    case 'completed':
      return 'happy';
    case 'failed':
    case 'budget_exceeded':
    case 'expired':
      return 'fearful';
    case 'awaiting_approval':
    case 'fixing':
    case 'rejected':
    case 'suspended':
      return 'doubt';
    default:
      return 'neutral';
  }
}

/** Mood of the agent as a whole (header, status banner). */
export function moodForAgent(s: { healthy: boolean; busy: boolean; waitingForHumans?: boolean; killSwitch?: string }): AvatarMood {
  if (!s.healthy || s.killSwitch === 'paused' || s.killSwitch === 'stopped') return 'fearful';
  if (s.killSwitch === 'tools_off' || s.waitingForHumans) return 'doubt';
  return s.busy ? 'neutral' : 'happy';
}
